27	
28	/** Card background per stock health — design uses white for OK, amber tint for LOW, red tint for OUT */
29	function cardBg(row: StockRow): string {
30	  const s = statusFor(row);
31	  if (s === 'out') return '#FFEBEE';
32	  if (s === 'low') return '#FFF8E1';
33	  return '#FFFFFF';
34	}
