36	/** Vertical color strip on the left edge of each stock card */
37	function stripColor(row: StockRow): string {
38	  const s = statusFor(row);
39	  if (s === 'out') return '#E53935';
40	  if (s === 'low') return '#F9A825';
41	  return '#43A047';
42	}
43	
44	/** Count text color per stock health */
45	function countColor(row: StockRow): string {
46	  const s = statusFor(row);
47	  if (s === 'out') return '#E53935';
48	  if (s === 'low') return '#F9A825';
49	  if (row.on_hand >= row.threshold * 2) return '#43A047';
50	  return '#66BB6A';
51	}
