53	// Stable keys drive the filter logic; labels are resolved per-render via
54	// t() so they follow the active language.
55	const STATUS_OPTIONS: { key: string; labelKey: StringKey }[] = [
56	  { key: 'All', labelKey: 'statusAll' },
57	  { key: 'In Stock', labelKey: 'statusInStock' },
58	  { key: 'Low', labelKey: 'statusLow' },
59	  { key: 'Out', labelKey: 'statusOut' },
60	];
61	
62	export function StockScreen({ route, navigation }: Props) {
63	  const t = useT();
64	  const { palette } = useTheme();
65	  const [rows, setRows] = useState<StockRow[]>([]);
66	  const [query, setQuery] = useState('');
67	  const [category, setCategory] = useState('All');
68	  const [statusFilter, setStatusFilter] = useState('All');
69	  const [refreshing, setRefreshing] = useState(false);
70	  // False until the first local read resolves — stops the "Nothing
71	  // matches" empty state flashing before readLocal() returns (warmCache
72	  // flips hasEverBeenWarm at login, before this screen mounts).
73	  const [loadedLocal, setLoadedLocal] = useState(false);
74	  // Smart Stock Card: which card is expanded to show action buttons.
75	  // Supports deep-linking via route params (e.g. from AlertsScreen).
76	  const [expandedBarcode, setExpandedBarcode] = useState<string | null>(
77	    route.params?.expandBarcode ?? null,
78	  );
79	  const stockStatus = useCacheStatus('stock');
80	  // Skeleton until the first local read lands, OR while we have NEVER
81	  // successfully warmed the stock cache this session AND we're not
82	  // sitting on a known failure state (error / offline) — in those
83	  // terminal states we'd rather show whatever's in local SQLite than a
84	  // forever-spinner.
85	  const showInitialSkeleton =
86	    !loadedLocal ||
87	    (!stockStatus.hasEverBeenWarm &&
88	      stockStatus.state !== 'error' &&
89	      stockStatus.state !== 'offline');
90	
91	  const categoryOptions = useMemo<FilterOption[]>(() => {
92	    const cats = new Set(rows.map((r) => r.category).filter(Boolean) as string[]);
93	    return [{ key: 'All', label: t('allCategories') }, ...Array.from(cats).sort().map((c) => ({ key: c, label: c }))];
94	  }, [rows, t]);
95	  const statusOptions = useMemo<FilterOption[]>(
96	    () => STATUS_OPTIONS.map((o) => ({ key: o.key, label: t(o.labelKey) })),
97	    [t],
98	  );
99	
100	  // Pull the latest stock from the server and replace the local cache.
101	  // Throws on failure so refetchThrottled() can flip the cache state to
102	  // error / offline appropriately. flushOnce() runs first so any
103	  // just-queued local writes hit the server before this read.
104	  const fetchRemote = useCallback(async () => {
105	    await flushOnce().catch(() => {});
106	    const remote = await api.fetch.stock();
107	    await replaceStockFromRemote(
108	      remote.map((r) => ({
109	        barcode: r.barcode,
110	        name: r.name,
111	        category: r.category,
112	        unit: r.unit,
113	        pack_size: r.pack_size != null ? Number(r.pack_size) : null,
114	        dispense_mode: r.dispense_mode ?? 'pack',
