132	    setRows(await listStock());
133	    setLoadedLocal(true);
134	  }, []);
135	
136	  // Always refetch on focus; the throttle in refetchThrottled stops a
137	  // back-tap burst from firing N parallel requests.
138	  const refresh = useCallback(async () => {
139	    await refetchThrottled('stock', fetchRemote);
140	    await readLocal();
141	  }, [fetchRemote, readLocal]);
142	
143	  useEffect(() => {
144	    void readLocal();
145	    void refresh();
146	    const unsub = navigation.addListener('focus', () => { void refresh(); });
147	    // Subscribe to cache state changes too — warmCache or
148	    // post-write invalidation in flushOnce can update the cache from
149	    // outside this screen; re-read SQLite so the list reflects it.
150	    const unsubCache = onCacheStateChange('stock', (s) => {
151	      if (s.state === 'warm') void readLocal();
