157	    // Pull-to-refresh is a user-initiated request — never skip it.
158	    invalidateRefetchThrottle('stock');
159	    setRefreshing(true);
160	    try {
161	      await refresh();
162	    } finally {
163	      setRefreshing(false);
164	    }
