167	  const filtered = useMemo(() => {
168	    const q = query.trim().toLowerCase();
169	    return rows.filter((r) => {
170	      if (category !== 'All' && r.category !== category) return false;
171	      if (statusFilter !== 'All') {
172	        const s = statusFor(r);
173	        if (statusFilter === 'In Stock' && s !== 'ok') return false;
174	        if (statusFilter === 'Low' && s !== 'low') return false;
175	        if (statusFilter === 'Out' && s !== 'out') return false;
176	      }
177	      if (!q) return true;
178	      return r.name.toLowerCase().includes(q) || r.barcode.includes(q) || (r.category ?? '').toLowerCase().includes(q);
