256	              setExpandedBarcode((prev) => (prev === item.barcode ? null : item.barcode));
257	            }}
258	          >
259	            <View style={styles.row}>
260	              {/* Color strip — visual status indicator */}
261	              <View style={[styles.strip, { backgroundColor: stripColor(item) }]} />
262	              <View style={{ flex: 1 }}>
263	                <Text variant="titleMedium" style={{ fontWeight: '700' }}>{item.name}</Text>
264	                <Text
265	                  variant="bodyMedium"
266	                  color={palette.onSurfaceVariant}
267	                  style={{ marginTop: 2 }}
268	                >
