279	                  </Text>
280	                ) : statusFor(item) === 'low' ? (
281	                  <Text variant="labelMedium" color="#c98b00" style={{ textAlign: 'right', fontWeight: '700' }}>
282	                    LOW
283	                  </Text>
284	                ) : packSizeHint(item.pack_size, item.unit) ? (
285	                  <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ textAlign: 'right' }}>
286	                    {packSizeHint(item.pack_size, item.unit)}
287	                  </Text>
288	                ) : null}
289	              </View>
290	            </View>
291	
292	            {/* Smart Stock Card: action buttons (expanded only) */}
293	            {isExpanded && (
294	              <View style={styles.actionRow}>
