300	                  disabled={item.on_hand <= 0}
301	                />
302	                <ActionButton
303	                  icon={PackagePlus}
304	                  label={t('received')}
305	                  color={palette.tertiary ?? palette.primary}
306	                  onPress={() => navigation.navigate('Receiving', { barcode: item.barcode })}
307	                />
308	                <ActionButton
309	                  icon={Pencil}
310	                  label={t('editStock')}
311	                  color={palette.onSurfaceVariant}
312	                  onPress={() => navigation.navigate('EditStock', { barcode: item.barcode })}
313	                />
314	              </View>
315	            )}
316	          </Card>
317	          );
318	        }}
319	        ListEmptyComponent={
320	          <View style={styles.empty}>
321	            <Text variant="headlineSmall" style={{ textAlign: 'center' }}>
322	              {t('nothingMatches')}
323	            </Text>
324	            <Text
325	              variant="bodyLarge"
326	              color={palette.onSurfaceVariant}
327	              style={{ textAlign: 'center', marginTop: spacing.sm }}
328	            >
329	              {t('tryDifferentFilter')}
330	            </Text>
331	          </View>
