340	// ── ActionButton (local to StockScreen) ──────────────────────────────
341	
342	type ActionButtonProps = {
343	  icon: LucideIcon;
344	  label: string;
345	  color: string;
346	  onPress: () => void;
347	  disabled?: boolean;
348	};
349	
350	function ActionButton({ icon: Icon, label, color, onPress, disabled }: ActionButtonProps) {
351	  const { palette } = useTheme();
352	  return (
353	    <Pressable
354	      onPress={onPress}
355	      disabled={disabled}
356	      style={({ pressed }) => [
357	        styles.actionBtn,
358	        {
359	          backgroundColor: pressed
360	            ? palette.surfaceContainerHighest ?? 'rgba(0,0,0,0.08)'
361	            : palette.surfaceContainerHigh ?? 'rgba(0,0,0,0.04)',
362	          opacity: disabled ? 0.4 : 1,
363	        },
364	      ]}
365	    >
366	      <Icon size={20} color={color} strokeWidth={2.2} />
367	      <Text variant="labelMedium" color={color}>{label}</Text>
368	    </Pressable>
369	  );
370	}
371	
372	const styles = StyleSheet.create({
373	  safe: { flex: 1 },
374	  search: { paddingHorizontal: spacing.xl, paddingTop: spacing.sm },
375	  searchInput: {
376	    borderRadius: radius.md,
377	    borderWidth: 1.5,
378	    paddingHorizontal: spacing.lg,
379	    minHeight: 52,
380	    fontSize: 17,
381	  },
382	  filterRow: {
383	    flexDirection: 'row',
384	    gap: spacing.sm,
385	    paddingHorizontal: spacing.xl,
386	    paddingVertical: spacing.md,
387	  },
388	  list: { padding: spacing.xl, paddingTop: spacing.xs, paddingBottom: spacing.xxxl },
389	  row: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },
390	  strip: {
391	    width: 10,
392	    height: 44,
393	    borderRadius: 6,
394	  },
395	  countCol: { minWidth: 64, alignItems: 'flex-end' },
396	  actionRow: {
397	    flexDirection: 'row',
398	    gap: spacing.sm,
399	    marginTop: spacing.md,
400	    paddingTop: spacing.md,
401	    borderTopWidth: StyleSheet.hairlineWidth,
402	    borderTopColor: 'rgba(0,0,0,0.08)',
403	  },
404	  actionBtn: {
405	    flex: 1,
406	    alignItems: 'center',
