21	type Stats = {
22	  orders: number;
23	  stock: number;
24	  alerts: number;
25	};
26	
27	export function HomeScreen({ navigation }: Props) {
28	  const t = useT();
29	  const { palette } = useTheme();
30	  const [stats, setStats] = useState<Stats | null>(null);
31	  const [refreshing, setRefreshing] = useState(false);
32	
33	  // Tile loading is driven by cache status, not just `stats === null`.
34	  // Reading SQLite when the cache is cold returns zeros (empty table),
35	  // which would render "0" instead of a Skeleton — wrong. Use the
36	  // hasEverBeenWarm flag so once a cache has succeeded at least once
37	  // this session, subsequent refreshes don't re-skeleton the tile.
38	  const stockStatus = useCacheStatus('stock');
39	  const ordersStatus = useCacheStatus('orders');
40	  const alertsStatus = useCacheStatus('alerts');
41	  const stillLoading = (s: { state: string; hasEverBeenWarm: boolean }) =>
42	    !s.hasEverBeenWarm && s.state !== 'error' && s.state !== 'offline';
43	
44	  // Stock fetch — pulled out separately so refetchThrottled can manage
45	  // its cache state. Throws on failure so the state machine sees it.
46	  const fetchStock = useCallback(async () => {
47	    await flushOnce().catch(() => {});
48	    const remote = await api.fetch.stock();
49	    await replaceStockFromRemote(
50	      remote.map((r) => ({
51	        barcode: r.barcode,
52	        name: r.name,
53	        category: r.category,
54	        unit: r.unit,
55	        pack_size: r.pack_size != null ? Number(r.pack_size) : null,
56	        on_hand: Number(r.on_hand),
57	        threshold: Number(r.threshold),
58	      })),
59	    );
60	  }, []);
61	
62	  const fetchOrders = useCallback(async () => {
63	    const remoteOrders = await api.fetch.orders();
64	    await upsertOrdersFromRemote(remoteOrders);
65	  }, []);
66	
67	  const readLocal = useCallback(async () => {
68	    const [stock, openOrders, alerts] = await Promise.all([
69	      listStock(),
70	      listOpenOrders(),
71	      listLowOrOut(),
72	    ]);
73	    setStats({ stock: stock.length, orders: openOrders.length, alerts: alerts.length });
74	  }, []);
75	
76	  // Each tile-relevant cache key gets its own throttled refetch in
77	  // parallel. Errors flip the per-key state via refetchThrottled; we
78	  // never throw out of here so the UI stays responsive.
79	  const refresh = useCallback(async () => {
80	    await Promise.all([
81	      refetchThrottled('stock', fetchStock),
82	      refetchThrottled('orders', fetchOrders),
83	    ]);
84	    await readLocal();
85	  }, [fetchStock, fetchOrders, readLocal]);
86	
87	  useEffect(() => {
88	    void readLocal();
89	    void refresh();
90	    const unsub = navigation.addListener('focus', () => { void refresh(); });
91	    // Re-read SQLite whenever another caller (warmCache, post-write
92	    // invalidation in flushOnce) successfully refreshes one of our
93	    // upstream caches. Cheap because listStock/listOpenOrders/
94	    // listLowOrOut are local-only SELECTs.
95	    const unsubStock = onCacheStateChange('stock', (s) => {
96	      if (s.state === 'warm') void readLocal();
97	    });
98	    const unsubOrders = onCacheStateChange('orders', (s) => {
99	      if (s.state === 'warm') void readLocal();
100	    });
101	    return () => { unsub(); unsubStock(); unsubOrders(); };
102	  }, [navigation, refresh, readLocal]);
103	
104	  const onRefresh = useCallback(async () => {
105	    invalidateRefetchThrottle('stock');
106	    invalidateRefetchThrottle('orders');
107	    setRefreshing(true);
108	    try {
109	      await refresh();
110	    } finally {
111	      setRefreshing(false);
112	    }
113	  }, [refresh]);
114	
115	  return (
116	    <SafeAreaView edges={['top']} style={[styles.safe, { backgroundColor: palette.background }]}>
117	      <ScrollView
118	        contentContainerStyle={styles.scroll}
119	        refreshControl={
120	          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />
121	        }
122	      >
123	        <View style={styles.header}>
124	          <View style={styles.headerRow}>
125	            <View style={{ flex: 1 }}>
126	              <Text variant="headlineMedium">
127	                {t('greeting')}, {getSession()?.guardName ?? ''}
128	              </Text>
