134	          </View>
135	        </View>
136	
137	        {/* Hero card — gradient-feel scan CTA */}
138	        <Pressable
139	          onPress={() => navigation.navigate('Scanner')}
140	          style={({ pressed }) => [
141	            styles.heroCard,
142	            {
143	              backgroundColor: pressed ? '#7a2278' : palette.primary,
144	              shadowColor: palette.primary,
145	            },
146	          ]}
147	        >
148	          <View style={styles.heroIcon}>
149	            <ScanLine size={30} color="#fff" strokeWidth={2.2} />
150	          </View>
151	          <Text variant="headlineMedium" color="#fff" style={{ marginTop: spacing.lg, fontWeight: '800', letterSpacing: -0.5 }}>
152	            {t('startScanning')}
153	          </Text>
154	          <Text variant="bodyMedium" color="rgba(255,255,255,0.85)" style={{ marginTop: spacing.xxs }}>
155	            {t('scanItem')}
156	          </Text>
157	        </Pressable>
158	
159	        <View style={styles.tilesRow}>
160	          <Tile
161	            label={t('receiving')}
162	            value={stats?.orders}
163	            loading={stillLoading(ordersStatus) || stats === null}
164	            sub={t('expectedToday')}
165	            Icon={Truck}
166	            onPress={() => navigation.navigate('Orders')}
167	          />
168	          <Tile
169	            label={t('stock')}
170	            value={stats?.stock}
171	            loading={stillLoading(stockStatus) || stats === null}
172	            sub={t('stockSub')}
173	            Icon={Package}
174	            onPress={() => navigation.navigate('Stock')}
175	          />
176	        </View>
177	
178	        <View style={styles.tilesRow}>
179	          <Tile
180	            label={t('dispense')}
181	            sub={t('dispenseSub')}
182	            Icon={HandCoins}
183	            onPress={() => navigation.navigate('Dispense')}
184	            valueSlot={
185	              <View style={{ height: 40, marginTop: spacing.xs, justifyContent: 'center' }}>
186	                <ArrowRight size={30} color={palette.primary} strokeWidth={2} />
187	              </View>
188	            }
189	          />
190	          <Tile
191	            label={t('alerts')}
192	            value={stats?.alerts || undefined}
193	            loading={stillLoading(alertsStatus) || stats === null}
194	            sub={t('alertsSub')}
195	            Icon={Bell}
196	            tone={stats && stats.alerts > 0 ? 'warn' : 'neutral'}
197	            onPress={() => navigation.navigate('Alerts')}
198	            cardStyle={stats && stats.alerts > 0 ? { backgroundColor: '#FFF8E1' } : undefined}
199	          />
200	        </View>
201	
202	        {/* Sync queue — full-width row card */}
203	        <View style={styles.tilesRow}>
204	          <Card tone="elevated" onPress={() => navigation.navigate('Outbox')} style={styles.tile}>
205	            <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.lg }}>
206	              <RefreshCw size={26} color={palette.primary} strokeWidth={2} />
207	              <View style={{ flex: 1 }}>
208	                <Text variant="labelLarge" color={palette.onSurfaceVariant}>
209	                  {t('syncQueue').toUpperCase()}
210	                </Text>
211	                <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.xxs }}>
212	                  {t('syncQueueSub')}
213	                </Text>
214	              </View>
215	              <QueueBadge />
216	            </View>
217	          </Card>
218	        </View>
219	      </ScrollView>
220	    </SafeAreaView>
