import React from 'react';
import { Pressable, StyleProp, View, ViewStyle } from 'react-native';
import { useTheme } from '../theme';
import { radius, spacing } from './tokens';

type Props = {
  onPress?: () => void;
  tone?: 'filled' | 'outlined' | 'elevated';
  padding?: keyof typeof spacing;
  style?: StyleProp<ViewStyle>;
  children: React.ReactNode;
};

export function Card({ onPress, tone = 'filled', padding = 'lg', style, children }: Props) {
  const { palette } = useTheme();
  const Container: any = onPress ? Pressable : View;
  const bg =
    tone === 'outlined'
      ? palette.surface
      : tone === 'elevated'
      ? palette.surfaceContainerLowest
      : palette.surfaceContainerLow;

  return (
    <Container
      onPress={onPress}
      android_ripple={onPress ? { color: palette.outlineVariant } : undefined}
      style={[
        {
          backgroundColor: bg,
          borderRadius: radius.lg,
          padding: spacing[padding],
          borderWidth: tone === 'outlined' ? 1 : 0,
          borderColor: palette.outlineVariant,
          ...(tone === 'elevated'
            ? {
                shadowColor: 'rgb(45,27,43)',
                shadowOpacity: 0.06,
                shadowRadius: 8,
                shadowOffset: { width: 0, height: 2 },
                elevation: 2,
              }
            : null),
          overflow: 'hidden',
        },
        style,
      ]}
    >
      {children}
    </Container>
  );
}

/**
 * Units module — barrel export.
 *
 * Centralises the unit registry (definitions) and conversion/formatting
 * helpers so consumers import from `../units` rather than reaching into
 * individual files.
 */

export { resolveUnit, isKnownUnit, allUnits } from './registry';
export type { UnitDef, UnitNature, UnitFamily } from './registry';

export {
  // Rounding
  roundQty,
  // Conversion
  packToBase,
  baseToPack,
  convertBetweenModes,
  // Mode resolution
  canSubdivide,
  isDecimalMode,
  stepSizeFor,
  minFor,
  maxForMode,
  // Display formatting
  formatOnHand,
  formatOnHandShort,
  packSizeHint,
  packChipLabel,
  unitChipLabel,
} from './convert';

