2	import React, { useState } from 'react';
3	import { Modal, Pressable, ScrollView, StyleSheet, View } from 'react-native';
4	import { radius, spacing, Text } from '../../../design';
5	import { haptic } from '../../../utils/haptics';
6	import { useTheme } from '../../../theme';
7	
8	export type FilterOption = {
9	  key: string;
10	  label: string;
11	};
12	
13	type Props = {
14	  label: string;
15	  options: FilterOption[];
16	  selected: string;
17	  onSelect: (key: string) => void;
18	};
19	
20	/**
21	 * A dropdown filter button that opens a bottom-sheet-style modal with options.
22	 * Compact trigger shows current selection with a chevron. Modal lists all
23	 * options with highlight on active item.
24	 */
25	export function FilterDropdown({ label, options, selected, onSelect }: Props) {
26	  const { palette } = useTheme();
27	  const [open, setOpen] = useState(false);
28	  const current = options.find((o) => o.key === selected);
29	
30	  const handleSelect = (key: string) => {
31	    haptic.tap();
32	    onSelect(key);
33	    setOpen(false);
34	  };
35	
36	  return (
37	    <>
38	      <Pressable
39	        onPress={() => setOpen(true)}
40	        style={[
41	          styles.trigger,
42	          {
43	            borderColor: selected !== 'All' ? palette.primary : palette.outlineVariant,
44	            backgroundColor: palette.surfaceContainerLowest,
45	          },
46	        ]}
47	      >
48	        <Text
49	          variant="labelLarge"
50	          color={selected !== 'All' ? palette.primary : palette.onSurface}
51	          numberOfLines={1}
52	        >
53	          {current?.label ?? label}
54	        </Text>
55	        <ChevronDown
56	          size={16}
57	          color={selected !== 'All' ? palette.primary : palette.onSurfaceVariant}
58	          strokeWidth={2.5}
59	        />
60	      </Pressable>
61	
62	      <Modal visible={open} transparent animationType="slide" onRequestClose={() => setOpen(false)}>
63	        <Pressable style={styles.backdrop} onPress={() => setOpen(false)}>
64	          <Pressable onPress={(e) => e.stopPropagation()} style={[styles.sheet, { backgroundColor: palette.surface }]}>
65	            <View style={[styles.sheetHeader, { borderBottomColor: palette.outlineVariant }]}>
66	              <Text variant="titleMedium">{label}</Text>
67	              <Pressable onPress={() => setOpen(false)} hitSlop={12}>
68	                <X size={20} color={palette.onSurfaceVariant} strokeWidth={2} />
69	              </Pressable>
70	            </View>
71	            <ScrollView style={styles.optionsList} bounces={false}>
72	              {options.map((opt) => {
73	                const active = opt.key === selected;
74	                return (
75	                  <Pressable
76	                    key={opt.key}
77	                    onPress={() => handleSelect(opt.key)}
78	                    style={[
79	                      styles.option,
80	                      active && { backgroundColor: `${palette.primary}14` },
81	                    ]}
82	                  >
83	                    <Text
84	                      variant="bodyLarge"
85	                      color={active ? palette.primary : palette.onSurface}
86	                      style={active ? { fontWeight: '600' } : undefined}
87	                    >
88	                      {opt.label}
89	                    </Text>
90	                    {active && (
91	                      <View style={[styles.activeDot, { backgroundColor: palette.primary }]} />
92	                    )}
93	                  </Pressable>
94	                );
95	              })}
96	            </ScrollView>
97	          </Pressable>
98	        </Pressable>
99	      </Modal>
100	    </>
101	  );
102	}
103	
104	const styles = StyleSheet.create({
