      unit: r.unit,
      pack_size: r.pack_size,
      dispense_mode: r.dispense_mode ?? 'pack',
      has_barcode: r.has_barcode ? 1 : 0,
      primary_barcode: r.primary_barcode ?? null,
      updated_at: Date.now(),
