53	type Props = NativeStackScreenProps<RootStackParamList, 'Dispense'>;
54	
55	// `value` is the canonical English string recorded on the dispense; only
56	// the displayed label is translated, so reporting/grouping stays stable
57	// regardless of the guard's chosen language.
58	const REASONS: { value: string; labelKey: StringKey }[] = [
59	  { value: 'Office use', labelKey: 'reasonOfficeUse' },
60	  { value: 'Pantry', labelKey: 'reasonPantry' },
61	  { value: 'Cleaning', labelKey: 'reasonCleaning' },
62	  { value: 'Maintenance', labelKey: 'reasonMaintenance' },
63	  { value: 'Other', labelKey: 'reasonOther' },
64	];
65	
66	// Stable keys drive the filter logic; labels are resolved per-render.
67	const STATUS_OPTIONS: { key: string; labelKey: StringKey }[] = [
68	  { key: 'All', labelKey: 'statusAll' },
69	  { key: 'In Stock', labelKey: 'statusInStock' },
70	  { key: 'Low', labelKey: 'statusLow' },
71	  { key: 'Out', labelKey: 'statusOut' },
72	];
73	
74	type VerifyStatus = 'verifying' | 'ok' | 'absent' | 'offline' | 'error';
75	
76	function isOfflineError(err: unknown): boolean {
77	  const msg = err instanceof Error ? err.message : String(err);
78	  return (
79	    msg.includes('Network request failed') ||
80	    msg.includes('TypeError: Network') ||
81	    msg.includes('Unable to resolve host')
82	  );
83	}
84	
85	/** Subtle background tint per stock health */
86	function cardBg(row: StockRow): string {
87	  const s = statusFor(row);
88	  if (s === 'out') return 'rgba(229, 57, 53, 0.07)';
89	  if (s === 'low') return 'rgba(249, 168, 37, 0.07)';
