97	  if (s === 'out') return '#E53935';
98	  if (s === 'low') return '#F9A825';
99	  if (row.on_hand >= row.threshold * 2) return '#43A047';
100	  return '#66BB6A';
101	}
102	
103	/**
104	 * The value a fresh dispense should open on. Starts at ONE unit of the
105	 * product's natural denomination — 1 pack for whole-pack goods, 1 base
106	 * unit (e.g. 1 kg) for divisible ones — capped at what's actually in
107	 * stock. Opening on the full available count read to guards as "take
108	 * everything"; dialing UP from a small amount is how dispensing works.
109	 * Returns the qty in packs (the denomination the lot system stores) plus
110	 * the mode the stepper should open in.
111	 */
112	function startingDispense(
113	  available: number,
114	  packSize: number | null | undefined,
115	  unit: string | null | undefined,
116	): { mode: DispenseMode; qty: number } {
117	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
118	  const divisible = canSubdivide(packSize, unit) && resolveUnit(unit).nature === 'continuous';
119	  const mode: DispenseMode = divisible ? 'unit' : 'pack';
120	  const oneUnitInPacks = mode === 'unit' ? 1 / ps : 1;
121	  return { mode, qty: Math.max(0, Math.min(available, oneUnitInPacks)) };
122	}
123	
124	export function DispenseScreen({ route, navigation }: Props) {
125	  const t = useT();
126	  const { palette } = useTheme();
127	  const kbHeight = useKeyboardHeight();
128	  const initialBarcode = route.params?.barcode;
129	  const [selected, setSelected] = useState<StockRow | null>(null);
130	  const [all, setAll] = useState<StockRow[]>([]);
131	  const [query, setQuery] = useState('');
132	  const [category, setCategory] = useState('All');
133	  const [statusFilter, setStatusFilter] = useState('All');
134	  const [qty, setQty] = useState(1);
135	  // Whether the guard is picking in 'pack' (whole/fractional packs)
136	  // or 'unit' (base units like kg, litres, bars). Driven by the
137	  // UnitAwareStepper chip toggle.
138	  const [dispenseMode, setDispenseMode] = useState<DispenseMode>('pack');
139	  const [reason, setReason] = useState(REASONS[0].value);
140	  const [saving, setSaving] = useState(false);
141	  const [initialLoading, setInitialLoading] = useState(true);
142	  const [refreshing, setRefreshing] = useState(false);
143	
144	  // JIT verification — fetch the server's authoritative on_hand the
145	  // moment a product is selected. Dispense MUST commit against the
146	  // freshest count so we never let a guard dispense 10 from a stock
147	  // of 8. Fail-closed: if the JIT fetch fails or times out, the
148	  // confirm button stays disabled until the user goes back and tries
149	  // again with network.
150	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('verifying');
151	  const [verifiedOnHand, setVerifiedOnHand] = useState<number | null>(null);
152	  /** Per-lot availability + current allocation. FEFO-ordered (earliest
153	   *  first). The big QtyStepper drives `qty` which re-suggests FEFO
154	   *  across these rows; users can override per-lot via the LotPicker
155	   *  (shown only when there are 2+ lots — single-lot products skip the
156	   *  picker). Total taken = sum(allocation.take). */
157	  const [allocation, setAllocation] = useState<LotAllocation[]>([]);
158	  const [availability, setAvailability] = useState<{ expiry: string | null; available: number }[]>([]);
159	
160	  const categoryOptions = useMemo<FilterOption[]>(() => {
161	    const cats = new Set(all.map((r) => r.category).filter(Boolean) as string[]);
162	    return [{ key: 'All', label: t('allCategories') }, ...Array.from(cats).sort().map((c) => ({ key: c, label: c }))];
163	  }, [all, t]);
164	  const statusOptions = useMemo<FilterOption[]>(
165	    () => STATUS_OPTIONS.map((o) => ({ key: o.key, label: t(o.labelKey) })),
166	    [t],
167	  );
168	
169	  // Pull the latest stock from the server and replace the local cache,
170	  // then re-read SQLite into the picker list. Mirrors StockScreen so the
171	  // dispense picker stays in sync with the source of truth — without this
172	  // it only ever showed whatever warmCache last left behind. Shares the
173	  // 'stock' refetch key with Stock/Alerts (same stock_levels table).
174	  const fetchRemote = useCallback(async () => {
175	    await flushOnce().catch(() => {});
176	    const remote = await api.fetch.stock();
177	    await replaceStockFromRemote(
178	      remote.map((r) => ({
179	        barcode: r.barcode,
180	        name: r.name,
181	        category: r.category,
182	        unit: r.unit,
183	        pack_size: r.pack_size != null ? Number(r.pack_size) : null,
184	        dispense_mode: r.dispense_mode ?? 'pack',
185	        on_hand: Number(r.on_hand),
186	        threshold: Number(r.threshold),
187	      })),
188	    );
189	    for (const r of remote) {
190	      await replaceLotsLocal(
191	        r.barcode,
192	        (r.lots ?? []).map((l) => ({ expiry_date: l.expiry_date, qty: Number(l.qty) })),
193	      );
194	    }
195	    await pruneLotsToBarcodes(remote.map((r) => r.barcode));
196	  }, []);
197	
198	  const readLocal = useCallback(async () => {
199	    setAll(await listStock());
200	  }, []);
201	
202	  const refresh = useCallback(async () => {
203	    await refetchThrottled('stock', fetchRemote);
204	    await readLocal();
205	  }, [fetchRemote, readLocal]);
206	
207	  useEffect(() => {
208	    readLocal().then(() => setInitialLoading(false));
209	    void refresh();
210	    const unsub = navigation.addListener('focus', () => { void refresh(); });
211	    return unsub;
212	  }, [navigation, refresh, readLocal]);
213	
214	  const onRefresh = useCallback(async () => {
215	    // Pull-to-refresh is user-initiated — bypass the throttle so a pull
216	    // right after a focus-fetch isn't swallowed.
217	    invalidateRefetchThrottle('stock');
218	    setRefreshing(true);
219	    try {
220	      await refresh();
221	    } finally {
222	      setRefreshing(false);
223	    }
224	  }, [refresh]);
225	
226	  useEffect(() => {
227	    if (initialBarcode) {
228	      findStock(initialBarcode).then((r) => r && setSelected(r));
229	    }
230	  }, [initialBarcode]);
231	
232	  // Whenever an item gets selected, re-run JIT verification. The
233	  // dependency on `selected?.barcode` (not the whole row) means
234	  // refetching only happens for an actual product change, not for the
235	  // optimistic update we apply after submit.
236	  useEffect(() => {
237	    if (!selected) {
238	      setVerifyStatus('verifying');
239	      setVerifiedOnHand(null);
240	      return;
241	    }
242	    let cancelled = false;
243	    setVerifyStatus('verifying');
244	    setVerifiedOnHand(null);
245	    const controller = new AbortController();
246	    const t = setTimeout(() => controller.abort(), 3000);
247	    (async () => {
248	      try {
249	        const remote = await api.fetch.stockOne(selected.barcode);
250	        if (cancelled) return;
251	        const remoteQty = Number(remote.on_hand);
252	        setVerifiedOnHand(remoteQty);
253	        setVerifyStatus('ok');
254	        // Open a fresh dispense low (1 unit of the natural denomination),
255	        // capped at the verified ceiling so the guard can never submit
256	        // over what exists. The stepper's `max` enforces the ceiling from
257	        // here on, so we don't need to clamp a carried-over qty.
258	        const { mode: startMode, qty: startQty } = startingDispense(
259	          remoteQty,
260	          selected.pack_size,
261	          selected.unit,
262	        );
263	        setDispenseMode(startMode);
264	        setQty(startQty);
265	
266	        // Build the lot picker state. Prefer the remote lots (verified
267	        // truth); fall back to the local lots cache when the server
268	        // returned no breakdown. Final fallback for legacy rows that
269	        // never received a lot write (existed before the lots
270	        // migration): synthesise a single lot from on_hand +
271	        // nearest_expiry so dispense still works on existing inventory.
272	        const remoteLots = remote.lots ?? [];
273	        let lots = remoteLots.length > 0
274	          ? remoteLots
275	          : (await listLots(selected.barcode)).map((l) => ({
276	              expiry_date: l.expiry_date,
277	              qty: Number(l.qty),
278	            }));
279	        if (lots.length === 0 && remoteQty > 0) {
280	          lots = [{
281	            expiry_date: remote.nearest_expiry ?? null,
282	            qty: remoteQty,
283	          }];
284	        }
285	        const nextAvailability = lots.map((l) => ({
286	          expiry: l.expiry_date,
287	          available: Number(l.qty),
288	        }));
289	        setAvailability(nextAvailability);
290	        setAllocation(suggestFEFO(nextAvailability, startQty));
291	      } catch (err) {
292	        if (cancelled) return;
293	        // 404: the server has no record of this barcode (might be a
294	        // device-only item never received server-side). Treat as
295	        // "absent" — block dispense; you can't dispense what the
296	        // server doesn't know exists.
297	        if (err instanceof ApiError && err.status === 404) {
298	          setVerifyStatus('absent');
299	          return;
300	        }
301	        if (err instanceof ApiError && err.status === 401) return;
302	
303	        // Couldn't reach the server (offline) or the check failed/timed
304	        // out. Offline-first decision: fall back to the last-known CACHED
305	        // count + local lots so the guard can still dispense. The write
306	        // queues in the outbox and reconciles on sync. Only the 404
307	        // "absent" case above stays blocked — everything else degrades to
308	        // the saved count rather than a dead button.
309	        const cachedQty = selected.on_hand;
310	        setVerifiedOnHand(cachedQty);
311	        const { mode: startMode, qty: startQty } = startingDispense(
312	          cachedQty,
313	          selected.pack_size,
314	          selected.unit,
315	        );
316	        setDispenseMode(startMode);
317	        setQty(startQty);
318	        let lots = (await listLots(selected.barcode)).map((l) => ({
319	          expiry_date: l.expiry_date,
320	          qty: Number(l.qty),
321	        }));
322	        if (lots.length === 0 && cachedQty > 0) {
323	          lots = [{ expiry_date: await getNearestExpiry(selected.barcode), qty: cachedQty }];
324	        }
325	        if (cancelled) return;
326	        const nextAvailability = lots.map((l) => ({
327	          expiry: l.expiry_date,
328	          available: Number(l.qty),
329	        }));
330	        setAvailability(nextAvailability);
331	        setAllocation(suggestFEFO(nextAvailability, startQty));
332	        setVerifyStatus(isOfflineError(err) ? 'offline' : 'error');
333	      } finally {
334	        clearTimeout(t);
335	      }
336	    })();
337	    return () => { cancelled = true; clearTimeout(t); controller.abort(); };
338	    // intentionally NOT in deps: `qty` would re-run the JIT on every
339	    // stepper tap; only refire when the selected barcode changes.
340	    // eslint-disable-next-line react-hooks/exhaustive-deps
341	  }, [selected?.barcode]);
342	
343	  const results = useMemo(() => {
344	    if (selected) return [];
345	    const q = query.trim().toLowerCase();
346	    // No cap: FlatList virtualizes, so the picker shows every stock item
347	    // when browsing. Capping here (was slice(0, 30)) silently hid items
348	    // for inventories with more than 30 SKUs.
349	    return all.filter((r) => {
350	      if (category !== 'All' && r.category !== category) return false;
351	      if (statusFilter !== 'All') {
352	        const s = statusFor(r);
353	        if (statusFilter === 'In Stock' && s !== 'ok') return false;
354	        if (statusFilter === 'Low' && s !== 'low') return false;
355	        if (statusFilter === 'Out' && s !== 'out') return false;
356	      }
357	      if (!q) return true;
358	      return r.name.toLowerCase().includes(q) || r.barcode.includes(q) || (r.category ?? '').toLowerCase().includes(q);
359	    });
360	  }, [all, query, selected, category, statusFilter]);
361	
362	  const totalTaken = useMemo(
363	    () => allocation.reduce((s, l) => s + (l.take || 0), 0),
364	    [allocation],
365	  );
366	
367	  const totalAvailable = useMemo(
368	    () => availability.reduce((s, l) => s + l.available, 0),
369	    [availability],
370	  );
371	
372	  /** Re-suggest FEFO whenever the user bumps the big "How many?" stepper.
373	   *  This intentionally overwrites manual per-lot edits — the per-lot
374	   *  picker is for fine-tuning AFTER the total is set.
375	   *
376	   *  When the user instead drives the per-lot picker, we sync `qty` to
377	   *  the new sum (see syncQtyFromAllocation). That sync would otherwise
378	   *  trigger this effect and overwrite their lot edit; the ref below
379	   *  swallows exactly one re-suggest pass to break the loop. */
380	  const skipNextFefoRecalc = useRef(false);
381	  useEffect(() => {
382	    if (availability.length === 0) return;
383	    if (skipNextFefoRecalc.current) {
384	      skipNextFefoRecalc.current = false;
385	      return;
386	    }
387	    setAllocation(suggestFEFO(availability, qty));
388	    // eslint-disable-next-line react-hooks/exhaustive-deps
389	  }, [qty]);
390	
391	  /** Per-lot edit handler — keeps the "How many?" stepper in lockstep
392	   *  with the sum of per-lot takes. Without this, the two surfaces drift:
393	   *  the upper stepper says "1" while the picker says "Taken 4 of 1". */
394	  const onAllocationChange = useCallback(
395	    (next: typeof allocation) => {
396	      const sum = next.reduce((s, l) => s + (l.take || 0), 0);
397	      if (sum !== qty) {
398	        skipNextFefoRecalc.current = true;
399	        setQty(sum);
400	      }
401	      setAllocation(next);
402	    },
403	    [qty, allocation],
404	  );
405	
406	  const submit = async () => {
407	    if (!selected || totalTaken <= 0) return;
408	    const session = getSession();
409	    setSaving(true);
410	    try {
411	      // totalTaken is always in pack-denomination (lot allocations are
412	      // in packs). Convert the guard's stepper value for the audit trail.
413	      const ps = (selected.pack_size ?? 1) > 0 ? (selected.pack_size ?? 1) : 1;
414	      const unitDef = resolveUnit(selected.unit);
415	      // For the audit trail: what the guard actually saw on screen.
416	      const dispenseQty = dispenseMode === 'unit'
417	        ? qty  // the raw value they typed (e.g. "2 litres")
418	        : qty; // packs — recorded as-is
419	      const dispenseUnit = dispenseMode === 'unit'
420	        ? unitDef.symbol
421	        : 'pack';
422	
423	      const picks = allocation
424	        .filter((l) => l.take > 0)
425	        .map((l) => ({ expiry_date: l.expiry, qty: l.take }));
426	      await enqueue('dispense', {
427	        id: `dsp_${nanoid(12)}`,
428	        barcode: selected.barcode,
429	        product_name: selected.name,
430	        qty: totalTaken,
431	        // Audit trail: what the guard saw on screen ("2 litres" vs "1 pack")
432	        dispense_qty: dispenseQty,
433	        dispense_unit: dispenseUnit,
434	        // Soft-nudge model: server records what the guard actually
435	        // picked rather than enforcing FEFO. Empty picks → server
436	        // falls back to FEFO (the suggestion the user accepted).
437	        lot_picks: picks,
438	        reason,
439	        // taken_by is now always the logged-in guard — no separate
440	        // free-text "who" field. Removes one mandatory input from the
441	        // dispense flow.
442	        taken_by: session?.guardName ?? null,
443	        issued_at: Date.now(),
444	        performed_by: session?.guardId ?? null,
445	        performed_by_name: session?.guardName ?? null,
446	      });
447	      await decrementLotsLocal(
448	        selected.barcode,
449	        totalTaken,
450	        picks.map((p) => ({ expiry_date: p.expiry_date, qty: p.qty })),
451	      );
452	      await adjustOnHand(selected.barcode, -totalTaken);
453	      // Push the write + refresh stock before returning. `pullReads:false`
454	      // skips the catalog + orders GETs a dispense never touches, and the
455	      // stock/alerts caches now collapse into ONE stock pull — so this is
456	      // 2 quick calls (write + stock) instead of the previous 5-6 that made
457	      // "Done" drag. When offline, flushOnce returns immediately (the outbox
458	      // reconciles on reconnect), so dispense still feels instant on a dead
459	      // connection. Awaiting here (rather than firing in the background)
460	      // keeps the destination Stock list from briefly flashing the stale
461	      // pre-dispense count before the write lands.
462	      await flushOnce({ pullReads: false }).catch(() => {});
463	      haptic.success();
464	      navigation.goBack();
465	    } finally {
466	      setSaving(false);
467	    }
468	  };
469	
470	  if (!selected) {
471	    return (
472	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
473	        <AppBar title={t('dispense')} subtitle={t('dispenseSub')} onBack={() => navigation.goBack()} />
474	        <View style={styles.search}>
475	          <TextInput
476	            value={query}
477	            onChangeText={setQuery}
478	            placeholder={t('search')}
479	            placeholderTextColor={palette.onSurfaceVariant}
480	            style={[
481	            styles.searchInput,
482	            {
483	              backgroundColor: palette.surfaceContainerLowest,
484	              borderColor: palette.outlineVariant,
485	              color: palette.onSurface,
486	            },
487	          ]}
488	            autoFocus
489	          />
490	        </View>
491	        <View style={styles.filterRow}>
492	          <FilterDropdown
493	            label={t('filterCategory')}
494	            options={categoryOptions}
495	            selected={category}
496	            onSelect={setCategory}
497	          />
498	          <FilterDropdown
499	            label={t('filterStatus')}
500	            options={statusOptions}
501	            selected={statusFilter}
502	            onSelect={setStatusFilter}
503	          />
504	        </View>
505	        {initialLoading && all.length === 0 ? (
506	          <View style={styles.list}>
507	            {[0, 1, 2, 3].map((i) => (
508	              <View key={i} style={{ marginBottom: spacing.sm }}>
509	                <Card tone="filled" padding="lg">
510	                  <Skeleton width="55%" height={18} />
511	                  <View style={{ height: 6 }} />
512	                  <Skeleton width="75%" height={14} />
513	                </Card>
514	              </View>
515	            ))}
516	          </View>
517	        ) : (
518	          <FlatList
519	            data={results}
520	            keyExtractor={(r) => r.barcode}
521	            contentContainerStyle={styles.list}
522	            refreshControl={
523	              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />
524	            }
525	            ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}
526	            renderItem={({ item }) => (
527	              <Card tone="filled" padding="lg" onPress={() => setSelected(item)} style={{ backgroundColor: cardBg(item) }}>
528	                <View style={styles.pickerRow}>
529	                  <View style={{ flex: 1 }}>
530	                    <Text variant="titleMedium">{item.name}</Text>
531	                    <Text
532	                      variant="bodyMedium"
533	                      color={palette.onSurfaceVariant}
534	                      style={{ marginTop: 2 }}
535	                    >
536	                      {item.category ?? '—'}
537	                    </Text>
538	                  </View>
539	                  <Text variant="titleLarge" color={countColor(item)} style={{ fontWeight: '700' }}>
540	                    {formatOnHandShort(item.on_hand, item.pack_size, item.unit)}
541	                  </Text>
542	                </View>
543	              </Card>
544	            )}
545	            ListEmptyComponent={
546	              <View style={styles.empty}>
547	                <Text variant="bodyLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
548	                  {t('noItemsMatch')}
549	                </Text>
550	              </View>
551	            }
552	          />
553	        )}
554	      </View>
555	    );
556	  }
557	
558	  return (
559	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
560	      <AppBar
561	        title={t('dispense')}
562	        subtitle={selected.name}
563	        onBack={() => setSelected(null)}
564	      />
565	      <KeyboardAvoidingView
566	        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
567	        style={{ flex: 1 }}
568	      >
569	        <ScrollView
570	          contentContainerStyle={[styles.body, { paddingBottom: spacing.xl + kbHeight }]}
571	          keyboardShouldPersistTaps="handled"
572	        >
573	          {/* JIT verification banners. While verifying, the user can
574	              still scroll and pick a reason — they just can't confirm
575	              the dispense yet. */}
576	          {verifyStatus === 'verifying' && (
577	            <View style={styles.statusBanner}>
578	              <ActivityIndicator color={palette.primary} size="small" />
579	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginLeft: spacing.sm }}>
580	                {t('verifying')}
581	              </Text>
582	            </View>
583	          )}
584	          {/* Offline / failed check: dispense is still allowed against the
585	              saved count (offline-first), so this is an informational note,
586	              not a blocking error. */}
587	          {(verifyStatus === 'offline' || verifyStatus === 'error') && (
588	            <View
589	              style={[
590	                styles.statusBanner,
591	                { borderColor: palette.outline, backgroundColor: palette.surfaceContainerHigh ?? 'transparent' },
592	              ]}
593	            >
594	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
595	                {t('dispenseOfflineNote')}
596	              </Text>
597	            </View>
598	          )}
599	          {/* Absent: the server has no record of this item — dispense stays
600	              blocked. */}
601	          {verifyStatus === 'absent' && (
602	            <View
603	              style={[
604	                styles.statusBanner,
605	                { borderColor: palette.error, backgroundColor: palette.errorContainer ?? 'transparent' },
606	              ]}
607	            >
608	              <Text variant="bodyMedium" color={palette.error}>
609	                {t('itemNotOnServer')}
610	              </Text>
611	            </View>
612	          )}
613	
614	          <Card tone="elevated" padding="xl">
615	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
616	              {t('product').toUpperCase()}
617	            </Text>
618	            <Text variant="headlineSmall" style={{ marginTop: spacing.xs }}>
619	              {selected.name}
620	            </Text>
621	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.xs }}>
622	              {formatOnHand(verifiedOnHand ?? selected.on_hand, selected.pack_size, selected.unit)}
623	              {' '}{t('onHand')}
624	            </Text>
625	          </Card>
626	
627	          {/* Pack visual — fill box showing remaining stock after dispense */}
628	          {verifyStatus !== 'verifying' && (
629	            <PackVisual
630	              totalCapacity={verifiedOnHand ?? selected.on_hand}
631	              remaining={Math.max(0, (verifiedOnHand ?? selected.on_hand) - totalTaken)}
632	              unit={selected.unit ?? 'packs'}
633	              threshold={selected.threshold}
634	            />
635	          )}
636	
637	          {/* Quantity area. We can't know whether this is a single-lot
638	              (stepper only) or multi-lot (stepper + per-lot picker)
639	              product until JIT verification returns the lot breakdown.
640	              Rendering the stepper immediately and letting the LotPicker
641	              pop in later is jarring, so while verifying we show a
642	              skeleton placeholder and commit the real controls in one
643	              paint once the breakdown is known. */}
644	          {verifyStatus === 'verifying' ? (
645	            <View style={styles.qtySection}>
646	              <View style={{ alignItems: 'center' }}>
647	                <Skeleton width={120} height={16} />
648	              </View>
649	              <Skeleton width="100%" height={64} rounded="md" />
650	            </View>
651	          ) : (
652	            <>
653	              {/* Primary "How many?" stepper — the familiar input. Max is
654	                  the verified total available across all lots so the user
655	                  can't ask for more than exists. */}
656	              <View style={styles.qtySection}>
657	                <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
658	                  {t('howMany').toUpperCase()}
659	                </Text>
660	                <UnitAwareStepper
661	                  // `qty` is always stored in packs (the denomination the
662	                  // lot system expects). The stepper wants `value` in the
663	                  // active mode's unit, so re-express packs → base units
664	                  // when the guard is in 'unit' mode. Without this the
665	                  // number collapsed through baseToPack on every render.
666	                  value={
667	                    dispenseMode === 'unit'
668	                      ? packToBase(qty, (selected.pack_size ?? 1) > 0 ? (selected.pack_size ?? 1) : 1)
669	                      : qty
670	                  }
671	                  onChange={(v, m) => {
672	                    // When in 'unit' mode, convert to packs for lot allocation
673	                    // so totalTaken stays in the pack denomination the lot
674	                    // system expects. Store the pack value at FULL precision —
675	                    // rounding packs to 3 dp here is too coarse to reconstruct
676	                    // the base-unit value when pack_size doesn't divide evenly
677	                    // (5.1 kg → 1.017 packs → 6.102 kg drift). The stepper's
678	                    // own display rounding keeps the on-screen number clean.
679	                    if (m === 'unit') {
680	                      const ps = (selected.pack_size ?? 1) > 0 ? (selected.pack_size ?? 1) : 1;
681	                      setQty(baseToPack(v, ps));
682	                    } else {
683	                      setQty(v);
684	                    }
685	                  }}
686	                  packSize={selected.pack_size}
687	                  unit={selected.unit}
688	                  maxPacks={(totalAvailable || verifiedOnHand || selected.on_hand) || 0}
689	                  mode={dispenseMode}
690	                  onModeChange={setDispenseMode}
691	                />
