693	
694	              {/* Per-lot picker. Only worth showing when there are 2+ lots —
695	                  for the common single-lot case the big stepper above is the
696	                  whole story. FEFO is highlighted as "← suggested"; guard
697	                  can override per-row. */}
698	              {availability.length > 1 && (
699	                <LotPicker
700	                  lots={allocation}
701	                  onChange={onAllocationChange}
702	                  desiredQty={qty}
703	                  unit={selected.unit ?? null}
704	                  packSize={selected.pack_size ?? null}
705	                  decimal={resolveUnit(selected.unit).nature === 'continuous'}
706	                />
707	              )}
708	            </>
709	          )}
710	
711	          <View>
712	            <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ marginBottom: spacing.sm }}>
713	              {t('reason').toUpperCase()}
714	            </Text>
715	            <View style={styles.chipRow}>
716	              {REASONS.map((r) => (
717	                <Chip
718	                  key={r.value}
719	                  label={t(r.labelKey)}
720	                  selected={r.value === reason}
721	                  onPress={() => setReason(r.value)}
722	                />
723	              ))}
724	            </View>
725	          </View>
726	
727	          {/* Who took it: always the logged-in guard. No need for a
728	              text input; just surface their name so they know the
729	              record will be filed under them. */}
730	          <View style={{ marginTop: spacing.md }}>
731	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
732	              {t('whoTook').toUpperCase()}
733	            </Text>
734	            <Text variant="titleMedium" style={{ marginTop: spacing.xs }}>
735	              {getSession()?.guardName ?? '—'}
736	            </Text>
737	          </View>
738	        </ScrollView>
739	
740	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
741	          {/* Confirm is blocked only while the live check is still running
742	              ('verifying') or when the server has no record of the item
743	              ('absent'). Offline / failed checks fall back to the saved
744	              count and are allowed (offline-first) — the write queues in
745	              the outbox and reconciles on sync. */}
746	          <Button
747	            label={t('confirm')}
748	            onPress={submit}
749	            loading={saving}
750	            disabled={verifyStatus === 'verifying' || verifyStatus === 'absent' || totalTaken <= 0}
751	            size="lg"
752	            fullWidth
753	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
754	          />
755	        </View>
756	      </KeyboardAvoidingView>
757	    </View>
758	  );
759	}
760	
