1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { AlertTriangle, Check, ScanLine } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useEffect, useMemo, useState } from 'react';
5	import { Platform, ScrollView, StyleSheet, View, KeyboardAvoidingView } from 'react-native';
6	import {
7	  AppBar,
8	  Button,
9	  Card,
10	  IconButton,
11	  radius,
12	  spacing,
13	  StatusPill,
14	  Text,
15	} from '../../../design';
16	import { addReceivedQty, findOpenItemByBarcode, OrderItem } from '../../../db/orders';
17	import { enqueue } from '../../../db/outbox';
18	import { trackExpiry } from '../../../db/expiry';
19	import { findProduct, Product } from '../../../db/products';
20	import { learnBarcode, findOpenItemByProductId } from '../../../db/catalog';
21	import { adjustOnHand, findStock, upsertStock } from '../../../db/stock';
22	import { addLotLocal } from '../../../db/lots';
23	import { getSession } from '../../../auth/session';
24	import { useT } from '../../../i18n';
25	import { useTheme } from '../../../theme';
26	import { RootStackParamList } from '../../../navigation/types';
27	import { flushOnce } from '../../../sync/syncService';
28	import { haptic } from '../../../utils/haptics';
29	import { useOrderSession } from '../components/OrderSessionContext';
30	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
31	import { BatchEditor, Batch } from '../components/BatchEditor';
32	
33	type Props = NativeStackScreenProps<RootStackParamList, 'Receiving'>;
34	
35	/** Convert Date object to ISO date string */
36	function toISO(d: Date): string {
37	  return d.toISOString().split('T')[0];
38	}
39	
40	const QUICK_MONTHS = [
41	  { label: '3 mo', months: 3 },
42	  { label: '6 mo', months: 6 },
43	  { label: '1 yr', months: 12 },
44	  { label: '2 yr', months: 24 },
45	];
46	
47	export function ReceivingScreen({ route, navigation }: Props) {
48	  const t = useT();
49	  const { palette } = useTheme();
50	  const kbHeight = useKeyboardHeight();
51	  const { barcode, productId, productName: paramProductName, unit: paramUnit, packSize: paramPackSize } = route.params;
52	  const orderSession = useOrderSession();
53	  const [product, setProduct] = useState<Product | null>(null);
54	  const [item, setItem] = useState<OrderItem | null>(null);
55	  const [saving, setSaving] = useState(false);
56	
57	  // One row per distinct expiry. Default to a single batch carrying
58	  // qty=1 — matches the 90% case of "one pack, one expiry". Guard taps
59	  // "+ Add another expiry batch" to break into groups.
60	  // ReceivingScreen always asks in packs (integer) even for divisible
61	  // products: physical intake is always whole packs. The translation to
62	  // base units (e.g. 3 packs × 5 kg → 15 kg lot qty) happens at submit.
63	  // Initial batch is "unset" (undefined) — forces the guard to actively
64	  // pick "Pick expiry" or "No expiry" rather than silently defaulting.
65	  const [batches, setBatches] = useState<Batch[]>([{ qty: 1, expiry: undefined }]);
66	  const qty = useMemo(() => batches.reduce((s, b) => s + (b.qty || 0), 0), [batches]);
67	
68	  // Resolved product name: canonical name takes priority over legacy product name
69	  const resolvedName = paramProductName ?? product?.name ?? 'Unknown';
70	  const resolvedUnit = paramUnit ?? product?.unit ?? null;
71	  const resolvedPackSize = paramPackSize ?? null;
72	  const packDisplay =
73	    resolvedPackSize != null && resolvedUnit
74	      ? `${resolvedPackSize} ${resolvedUnit}`
75	      : resolvedUnit ?? null;
76	
77	  useEffect(() => {
78	    (async () => {
79	      setProduct(await findProduct(barcode));
80	      const stockRow = await findStock(barcode);
81	      // If we have a productId from catalog, look up order item by product_id
82	      if (productId) {
83	        const byProduct = await findOpenItemByProductId(productId);
84	        setItem(byProduct as OrderItem | null);
85	      } else {
86	        setItem(await findOpenItemByBarcode(barcode));
87	      }
88	    })();
89	  }, [barcode, productId]);
90	
91	  /** Convert a "packs received" integer into the units stored in lots:
92	   *  Under the new unit-aware system, all stock is stored in packs. */
93	  const toLotQty = (packsQty: number): number => {
94	    return packsQty;
95	  };
96	
97	  // Auto-fill expiry on the (single) initial batch from the last scanned
98	  // item in this order session — matches "same expiry as the last pack
99	  // off the truck" behaviour.
100	  useEffect(() => {
101	    if (orderSession.lastExpiry && batches.length === 1 && batches[0].expiry === undefined) {
102	      setBatches([{ qty: batches[0].qty, expiry: orderSession.lastExpiry }]);
103	    }
104	    // eslint-disable-next-line react-hooks/exhaustive-deps
105	  }, [orderSession.lastExpiry]);
106	
107	  /** Standalone receipt path — when no order session is active */
108	  const persistStandalone = async (flagged: boolean) => {
109	    const session = getSession();
110	    // One receipt per distinct expiry batch. Each batch carries its
111	    // total qty (no exploding into N qty=1 rows).
112	    // Coerce the editor's tri-state (undefined = unset) into the binary
113	    // string|null the persistence layer expects. Unset at submit time
114	    // = same as "no expiry" — submit shouldn't block on an indecision.
115	    const cleanBatches = batches
116	      .filter((b) => b.qty > 0)
117	      .map((b) => ({ ...b, expiry: b.expiry ?? null }));
118	    // For divisible products, the lot is stored in base units (pack count
119	    // × pack_size). Pack-mode lots keep the raw count.
120	    const receipts: Array<{ id: string; qty: number; expiry: string | null }> =
121	      cleanBatches.map((b) => ({
122	        id: `rcp_${nanoid(12)}`,
123	        qty: toLotQty(b.qty),
124	        expiry: b.expiry,
125	      }));
126	
127	    // The first receipt's id is what we use to link mismatch flags etc.
128	    const id = receipts[0]?.id ?? `rcp_${nanoid(12)}`;
129	
130	    for (const r of receipts) {
131	      await enqueue('receipt', {
132	        id: r.id,
133	        order_id: item?.order_id ?? null,
134	        order_item_id: item?.id ?? null,
135	        product_id: productId ?? null,
136	        barcode,
137	        product_name: resolvedName,
138	        qty: r.qty,
139	        expiry_date: r.expiry,
140	        flagged,
141	        scanned_at: Date.now(),
142	        performed_by: session?.guardId ?? null,
143	        performed_by_name: session?.guardName ?? null,
144	      });
145	      // Mirror the lot locally so EditStock / Dispense see the new
146	      // batch before the next sync round-trip.
147	      await addLotLocal(barcode, r.expiry, r.qty);
148	    }
149	
150	    // Barcode learning: if this receipt was resolved via canonical catalog,
151	    // permanently map this barcode to the product_id for auto-resolution.
152	    if (productId && !barcode.startsWith('catalog_')) {
153	      await learnBarcode(barcode, productId, 'scan');
154	      // Also tell the backend to learn it
155	      await enqueue('learn_barcode', {
156	        barcode,
157	        product_id: productId,
158	      }).catch(() => {});
159	    }
160	    if (flagged) {
161	      await enqueue('mismatch_flag', {
162	        id: `flg_${nanoid(12)}`,
163	        receipt_id: id,
164	        order_item_id: item?.id ?? null,
165	        barcode,
166	        expected: item?.expected_qty ?? null,
167	        received_total: (item?.received_qty ?? 0) + qty,
168	        flagged_at: Date.now(),
169	      });
170	    }
171	    // Order item received_qty and stock on_hand track the same lot units —
172	    // packs for pack-mode, base units for divisible. Mirror toLotQty.
173	    const totalLotQty = toLotQty(qty);
174	    if (item) await addReceivedQty(item.id, totalLotQty);
175	
176	    const existing = await findStock(barcode);
177	    if (existing) {
178	      await adjustOnHand(barcode, totalLotQty);
179	    } else {
180	      await upsertStock({
181	        barcode,
182	        name: resolvedName,
183	        category: product?.category ?? null,
184	        unit: resolvedUnit,
185	        pack_size: resolvedPackSize,
186	        dispense_mode: 'pack',
187	        on_hand: totalLotQty,
188	        threshold: 0,
189	      });
190	    }
191	
192	    flushOnce().catch(() => {});
193	
194	    // Track expiry for future alerts — one entry per batch (qty in lot units).
195	    for (const b of cleanBatches) {
196	      if (!b.expiry) continue;
197	      await trackExpiry({
198	        barcode,
199	        productName: resolvedName,
200	        expiryDate: b.expiry,
201	        qty: toLotQty(b.qty),
202	        receiptId: id,
203	        performedBy: session?.guardId ?? null,
204	        performedByName: session?.guardName ?? null,
205	      });
206	    }
207	  };
208	
209	  /** Add to order session */
210	  const addToSession = () => {
211	    const cleanBatches = batches.filter((b) => b.qty > 0);
212	    const totalQty = cleanBatches.reduce((s, b) => s + b.qty, 0);
213	
214	    orderSession.addItem({
215	      barcode,
216	      productId: productId ?? null,
217	      name: resolvedName,
218	      category: product?.category ?? null,
219	      unit: resolvedUnit,
220	      packSize: resolvedPackSize,
221	      qty: totalQty,
222	      // Coerce tri-state expiry into the binary string|null the session
223	      // expects — submit shouldn't carry an indecision past this point.
224	      batches: cleanBatches.map((b) => ({ qty: b.qty, expiry: b.expiry ?? null })),
225	    });
226	    haptic.success();
227	    navigation.navigate('OrderSession');
228	  };
229	
230	  /** Standalone confirm (no active order session) */
231	  const confirmStandalone = async () => {
232	    setSaving(true);
233	    try {
234	      await persistStandalone(false);
235	      haptic.success();
236	      navigation.replace('DeliverySummary', {
237	        items: [{ name: resolvedName, category: product?.category ?? null, qty }],
238	        totalItems: 1,
239	        totalQty: qty,
240	        productName: resolvedName,
241	        qty,
242	        expected: item?.expected_qty ?? null,
243	        flagged: false,
244	      });
245	    } finally {
246	      setSaving(false);
247	    }
248	  };
249	
250	  const flagAndContinueStandalone = async () => {
251	    setSaving(true);
252	    try {
253	      await persistStandalone(true);
254	      haptic.warn();
255	      navigation.replace('DeliverySummary', {
256	        items: [{ name: resolvedName, category: product?.category ?? null, qty }],
257	        totalItems: 1,
258	        totalQty: qty,
259	        productName: resolvedName,
260	        qty,
261	        expected: item?.expected_qty ?? null,
262	        flagged: true,
263	      });
264	    } finally {
265	      setSaving(false);
266	    }
267	  };
268	
269	  const expected = item?.expected_qty ?? null;
270	  const alreadyIn = item?.received_qty ?? 0;
271	  const projected = alreadyIn + qty;
272	  const mismatch = expected !== null && projected > expected;
273	
274	  return (
275	    <KeyboardAvoidingView
276	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
277	      style={{ flex: 1 }}
278	    >
279	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
280	        <AppBar
281	          title={t('receiveItem')}
282	          onBack={() => navigation.goBack()}
283	          trailing={
284	            <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.xs }}>
285	              {expected !== null ? (
286	                <StatusPill
