1	import { nanoid } from 'nanoid/non-secure';
2	import React, { createContext, useCallback, useContext, useMemo, useState } from 'react';
3	import { enqueue } from '../../../db/outbox';
4	import { trackExpiry } from '../../../db/expiry';
5	import { adjustOnHand, findStock, upsertStock } from '../../../db/stock';
6	import { addLotLocal } from '../../../db/lots';
7	import { findProduct } from '../../../db/products';
8	import { addReceivedQty, findOpenItemByBarcode } from '../../../db/orders';
9	import { findOpenItemByProductId, learnBarcode } from '../../../db/catalog';
10	import { getSession } from '../../../auth/session';
11	import { flushOnce, syncOrders } from '../../../sync/syncService';
12	import { now } from '../../../db/database';
13	
14	export type OrderBatch = {
15	  qty: number;
16	  expiry: string | null; // ISO date, e.g. "2027-03-15"
17	};
18	
19	export type OrderSessionItem = {
20	  barcode: string;
21	  /** Canonical product id when the user picked one from the catalog. Lets
22	   *  the receipt link back to the right order_item and lets us learn the
23	   *  barcode → product mapping for next time. */
24	  productId?: string | null;
25	  name: string;
26	  category: string | null;
27	  unit: string | null;
28	  /** Pack size (unit value) for display: "qty × packSize unit". */
29	  packSize?: number | null;
30	  /** Total qty across all batches. Kept in sync with sum(batches[].qty). */
31	  qty: number;
32	  /** One row per distinct expiry. Single-expiry receipts have one batch;
33	   *  per-pack-expiry receipts have N batches of qty=1. */
34	  batches: OrderBatch[];
35	};
36	
37	type OrderSessionCtx = {
38	  items: OrderSessionItem[];
39	  addItem: (item: OrderSessionItem) => void;
40	  removeItem: (barcode: string) => void;
41	  updateItemQty: (barcode: string, qty: number) => void;
42	  clear: () => void;
43	  submitAll: () => Promise<void>;
44	  isActive: boolean;
45	  /** Last expiry date entered — used for "same as last" auto-fill */
46	  lastExpiry: string | null;
47	};
48	
49	const Ctx = createContext<OrderSessionCtx | null>(null);
50	
51	export function OrderSessionProvider({ children }: { children: React.ReactNode }) {
52	  const [items, setItems] = useState<OrderSessionItem[]>([]);
53	  const [lastExpiry, setLastExpiry] = useState<string | null>(null);
54	
55	  const addItem = useCallback((item: OrderSessionItem) => {
56	    // "Same as last" auto-fill uses the most recent non-null expiry the
57	    // guard explicitly set, regardless of which batch it came from.
58	    const lastNonNull = [...item.batches].reverse().find((b) => b.expiry)?.expiry;
59	    if (lastNonNull) setLastExpiry(lastNonNull);
60	    setItems((prev) => {
61	      const existing = prev.find((i) => i.barcode === item.barcode);
62	      if (existing) {
63	        // Merge by concatenating batches so distinct expiries survive a
64	        // re-scan of the same product.
65	        return prev.map((i) =>
66	          i.barcode === item.barcode
67	            ? {
68	                ...i,
69	                qty: i.qty + item.qty,
70	                batches: [...i.batches, ...item.batches],
71	              }
72	            : i,
73	        );
74	      }
75	      return [...prev, item];
76	    });
77	  }, []);
78	
79	  const removeItem = useCallback((barcode: string) => {
80	    setItems((prev) => prev.filter((i) => i.barcode !== barcode));
81	  }, []);
82	
83	  const updateItemQty = useCallback((barcode: string, qty: number) => {
84	    // Collapses batches into a single batch carrying the earliest expiry —
85	    // safe default since manual qty edits can't reconcile against multiple
86	    // distinct expiries.
87	    setItems((prev) =>
88	      prev.map((i) => {
89	        if (i.barcode !== barcode) return i;
90	        const earliest = i.batches
91	          .map((b) => b.expiry)
